  for r in select distinct puzzle_id, new_groups from r1567_baseball loop
    if not exists (select 1 from public.baseball_connections_puzzles c where c.puzzle_id = r.puzzle_id) then
      missing := missing || r.puzzle_id;
    elsif exists (select 1 from public.baseball_connections_puzzles c where c.puzzle_id = r.puzzle_id and c.groups_json = r.new_groups) then
      already := already + 1;
    else
      update public.baseball_connections_puzzles c
         set groups_json = r.new_groups
       where c.puzzle_id = r.puzzle_id
         and c.groups_json in (select o.old_groups from r1567_baseball o where o.puzzle_id = r.puzzle_id);
      if found then
        rewritten := rewritten + 1;
      else
        drifted := drifted || r.puzzle_id;
      end if;
    end if;
  end loop;
